const Singleton = (() => {
  let instance;
  function createInstance() {
    return { id: Math.random() };
  }
  return {
    getInstance() {
      if (!instance) instance = createInstance();
      return instance;
    }
  };
})();

const a = Singleton.getInstance();
const b = Singleton.getInstance();
console.log(a === b);

const pubsub = {
  events: {},
  subscribe(event, fn) {
    this.events[event] = this.events[event] || [];
    this.events[event].push(fn);
    return () => this.events[event] = this.events[event].filter(f => f !== fn);
  },
  publish(event, data) {
    (this.events[event] || []).forEach(fn => fn(data));
  }
};

const unsub = pubsub.subscribe('test', data => console.log(data));
pubsub.publish('test', 'first');
unsub();
pubsub.publish('test', 'second');

class Counter {
  constructor() { this.value = 0; }
  increment() { this.value++; }
  decrement() { this.value--; }
}

class CommandInvoker {
  constructor() { this.history = []; }
  execute(command) {
    command.execute();
    this.history.push(command);
  }
  undo() {
    const cmd = this.history.pop();
    if (cmd) cmd.undo();
  }
}

const counter = new Counter();
const invoker = new CommandInvoker();
const incCmd = { execute: () => counter.increment(), undo: () => counter.decrement() };

invoker.execute(incCmd);
invoker.execute(incCmd);
invoker.undo();
console.log(counter.value);

